/* Token definitions for a parser generated by yacc.  */

#define NEWLINE 257
#define NUMBER 258
#define STRING 259
#define ERE 260
#define ERE_BAD 261
#define NAME 262
#define FUNC_NAME 263
#define BUILTIN 264
#define ASSIGNOP 265
#define RELOP 266
#define INCR 267
#define DECR 268
#define AND 269
#define OR 270
#define NOMATCH 271
#define APPEND 272
#define PIPE_GETLINE 273
#define ITEMSEP 274
#define VTERM 275
#define Begin 276
#define End 277
#define Break 278
#define Continue 279
#define Delete 280
#define Do 281
#define Else 282
#define Exit 283
#define For 284
#define Function 285
#define Getline 286
#define If 287
#define In 288
#define Next 289
#define Nextfile 290
#define Print 291
#define Printf 292
#define Return 293
#define While 294

#if !defined(YYSTYPE) && !defined(YYSTYPE_IS_DECLARED)
typedef union YYSTYPE {
    Tok *t;
    Node *n;
    List l;
    Func *f;
} YYSTYPE;
#define YYSTYPE_IS_DECLARED 1
#endif
extern YYSTYPE yylval;
int yyparse(void);
